// Not my code - just slightly modified for shadertoy
// Credit:
// https://x.com/XorDev/status/1880344887033569682
// @XorDev on X
// mini.gmshaders.com
// linktr.ee/xordev

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 r = iResolution.xy;
    vec2 p = (fragCoord.xy-r*.5)/r.y*mat2(8,-6,6,8);
    fragColor = vec4(0.0); 
    float t = iTime;

    for(float i = 0.; i < 50.; i++) {
        vec2 v = p+cos(i*i+(t+p.x*.1)*.03+i*vec2(11,9))*5.;
        // Use texture() to sample the noise texture
        float f = 3. + texture(iChannel0, (p+vec2(t*7.,0))/iChannelResolution[0].xy).x; 
        fragColor += (cos(sin(i)*vec4(1,2,3,1))+1.)*exp(sin(i*i+t))/length(max(v,vec2(v.x*f*.02,v.y)));
    }

    fragColor = tanh(pow(fragColor/1e2,vec4(1.5)));
}
